  function startRacket(p, serving, tick, underhand = false) {
    const r = p.racket;
    if (serving) {
      r.servePlaying = true;
      return;
    }
    r.frame = underhand ? 16 : 2;
    r.playing = true;
    r.ready = false;
    r.active = true;
    r.consumed = false;
    r.strokes++;
    r.strokeAt = tick;
  }
