        const py = top + cardH - 25;
        c.fillStyle = "#102620";
        c.fillRect(left + 6, py - 4, width - pad * 2 - 12, 20);
        icon(c, p.weapon.src, left + 9, py - 3, 18);
        c.fillStyle = "#ffedb8";
        c.font = "bold 11px system-ui";
        c.fillText(`${p.weapon.label} ${p.weapon.value}`, left + 31, py + 11, width - pad * 2 - 35);
